CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, plan TEXT NOT NULL DEFAULT 'free');
CREATE TABLE IF NOT EXISTS follows (follower_id TEXT NOT NULL, author_id TEXT NOT NULL, PRIMARY KEY (follower_id, author_id));
CREATE TABLE IF NOT EXISTS posts (id INTEGER PRIMARY KEY AUTOINCREMENT, author_id TEXT NOT NULL, body TEXT NOT NULL, visibility TEXT NOT NULL DEFAULT 'public');
CREATE TABLE IF NOT EXISTS ledger_entries (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL, amount_cents INTEGER NOT NULL, event_id TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS posts_author ON posts (author_id, id);
